  //    \u0447\u044C\u0438 \u0412\u0421\u0415 \u0432\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u0441\u0432\u044F\u0437\u0438 weights[*][j] \u0438 \u043F\u043E\u0440\u043E\u0433 biases[j] \u043E\u043D \u043F\u043E\u043B\u0443\u0447\u0438\u0442.
